#pragma once
// Category icons shared by both platforms. The Loader owns the Extend root icon
// and the generic fallback; every other category's appearance is declared by the
// package (declarative manifest "icon") or by the built-in runtime that registers
// it, and travels through the plugin UI descriptor. "black" is a standard SVG
// named colour both host renderers accept, so the artwork is byte-identical on
// macOS and Windows.
#define OPENSV2_ICON_ROOT "<svg xmlns=\"http://www.w3.org/2000/svg\" width=\"24\" height=\"24\" viewBox=\"0 0 24 24\"><rect width=\"24\" height=\"24\" fill=\"black\" opacity=\"0\"/><g transform=\"translate(3 3) scale(.75)\" fill=\"none\" stroke=\"black\" stroke-width=\"1.5\" stroke-linecap=\"round\" stroke-linejoin=\"round\"><rect x=\"3\" y=\"3\" width=\"6\" height=\"6\" rx=\"1\"/><rect x=\"3\" y=\"15\" width=\"6\" height=\"6\" rx=\"1\"/><rect x=\"15\" y=\"15\" width=\"6\" height=\"6\" rx=\"1\"/><path d=\"M14 6h8M18 2v8\"/></g></svg>"
